local H=game:GetService('HttpService')
local g=game.Players.LocalPlayer.PlayerGui.PunchWallHUD
local state={sequence=g:GetAttribute('LegacyPetActionCallbackSequence') or 0,expected=g:GetAttribute('Flow30ExpectedCallbackSequence'),action=g:GetAttribute('LegacyPetActionCallback'),index=g:GetAttribute('LegacyPetActionCallbackIndex'),token=g:GetAttribute('LegacyPetActionCallbackToken')}
assert(state.sequence==state.expected and state.action=='EquipPet' and state.index==2 and state.token=='Forest Pup','slot two Equip callback marker failed: '..H:JSONEncode(state))
return H:JSONEncode(state)

